//! Spending analysis — and the one thing it exists to get right: **a transfer is not spending**.
//!
//! Paying $300 from chequing to a credit card looks exactly like a $300 outflow. It is not
//! consumption — it is the same money in a different place, and the card minimum is ALREADY on the
//! obligation calendar. Counting it here as well subtracts it twice from the runway, which shortens
//! the answer in a way that looks like prudence and is simply wrong. Moving money between your own
//! accounts is the same mistake with no upside at all.
//!
//! So outflows are classified before anything is totalled: PAIRED (an outflow matched by an inflow of
//! the same size on another account within a few days), DEBT (a payment to an account declared as a
//! debt), FIXED (matched to a detected recurring charge), or VARIABLE. Only variable spending is
//! discretionary, and [`discretionary_monthly`] is the figure `runway` asks for.
//!
//! # Categorisation is data, deterministic, and local
//!
//! A table of keywords, not a model — a model here would mean sending somebody's merchant list
//! somewhere. What it cannot place is reported as UNCATEGORISED rather than dropped into an "other"
//! bucket, because a large "other" is a finding and a large "uncategorised" is an admission.
use crate::money::{money, sum, Currency, Money};
use crate::position::Position;
use crate::reconcile::ReconciledLedger;
use crate::recurring::Recurring;
use crate::txn::{days_between, merchant_key_default, month_of, Txn};

pub use categorise::categorise;
pub(crate) use median::median;
pub(crate) use whole_months::whole_months;
pub use discretionary_monthly::discretionary_monthly;
pub use top_categories::top_categories;

/// Why an outflow is or is not discretionary spending.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OutflowClass {
    Paired,
    Debt,
    Fixed,
    Variable,
}

impl OutflowClass {
    pub fn label(self) -> &'static str {
        match self {
            OutflowClass::Paired => "paired",
            OutflowClass::Debt => "debt",
            OutflowClass::Fixed => "fixed",
            OutflowClass::Variable => "variable",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ClassifiedOutflow {
    pub txn: Txn,
    pub kind: OutflowClass,
    /// Present for `Variable` and `Fixed`; NONE means nothing in the table matched — which is not
    /// the same as "other".
    pub category: Option<&'static str>,
    /// For `Paired`, the transaction on the other side.
    pub counterpart: Option<Txn>,
    /// For `Fixed`, the recurring charge it belongs to.
    pub recurring: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct CategoryTotal {
    pub category: &'static str,
    pub total: Money,
    pub count: usize,
    /// Median across the whole months observed — the usual month for this category.
    pub typical_month: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SpendingAnalysis {
    pub from: String,
    pub to: String,
    /// WHOLE months the medians are computed over.
    pub months_observed: usize,
    pub outflows: Vec<ClassifiedOutflow>,
    /// Standing charges — rent, subscriptions, insurance. Not a choice this month.
    pub fixed_monthly: Money,
    /// Everything else that was actually consumed. What `runway` wants.
    pub variable_monthly: Money,
    pub categories: Vec<CategoryTotal>,
    /// The same totals over VARIABLE outflows only.
    ///
    /// `categories` covers everything that was spent, fixed charges included, because "where does my
    /// money go" wants rent in the answer. Anything downstream that ALSO counts the obligation
    /// calendar must use this one instead — rent appears in both, and adding them counts it twice.
    /// That is not hypothetical: `viable` did exactly that and overstated every tier by the whole of
    /// the rent, which tells somebody they need to earn far more than they do.
    pub variable_categories: Vec<CategoryTotal>,
    /// Money that MOVED rather than left. Named so the exclusion is visible, never silent.
    pub transferred: Money,
    pub transfer_count: usize,
    /// Payments to declared debts, excluded because the calendar already has them.
    pub debt_payments: Money,
    /// Outflows nothing in the table could place. Reported, never bucketed as "other".
    pub uncategorised: Vec<Txn>,
    pub notes: Vec<String>,
}

/// The category table. DATA, so it can be read, argued with and extended without touching logic.
///
/// FIRST MATCH WINS, so the order is meaningful: fuel before transport, groceries before shopping.
pub const CATEGORY_RULES: &[(&str, &[&str])] = &[
    ("housing", &["rent", "mortgage", "landlord", "property mgmt", "hoa"]),
    ("utilities", &["electric", "power", "gas company", "water", "sewer", "internet", "broadband", "mobile", "wireless", "phone"]),
    ("insurance", &["insurance", "assurance", "geico", "allstate"]),
    ("healthcare", &["pharmacy", "dental", "clinic", "medical", "hospital", "optical", "vision"]),
    ("childcare", &["daycare", "childcare", "nursery", "preschool"]),
    ("education", &["tuition", "university", "college", "student loan", "bookstore"]),
    ("fuel", &["shell", "chevron", "exxon", "bp", "texaco", "fuel", "petrol", "gas station"]),
    ("transport", &["uber", "lyft", "transit", "metro", "parking", "toll", "rail", "airline", "airlines"]),
    ("groceries", &["grocery", "market", "supermarket", "safeway", "kroger", "aldi", "trader", "whole foods", "food store"]),
    ("dining", &["restaurant", "cafe", "coffee", "pizza", "grill", "diner", "bar", "brewing", "doordash", "grubhub", "seamless"]),
    ("subscriptions", &["netflix", "spotify", "hulu", "prime", "membership", "subscription", "patreon"]),
    ("entertainment", &["cinema", "theatre", "theater", "concert", "steam", "playstation", "xbox", "nintendo"]),
    ("shopping", &["amzn", "amazon", "target", "walmart", "costco", "store", "shop", "retail"]),
    ("fees", &["fee", "interest", "overdraft", "service charge", "atm"]),
    ("cash", &["withdrawal", "cash", "atm withdrawal"]),
];

pub struct SpendingOptions {
    /// How far apart the two halves of an internal transfer may be dated.
    pub transfer_window_days: i64,
}

impl Default for SpendingOptions {
    fn default() -> Self {
        SpendingOptions { transfer_window_days: 3 }
    }
}

pub fn analyse_spending(ledger: &ReconciledLedger, position: Option<&Position>, recurring: &[Recurring], currency: Currency, opts: &SpendingOptions) -> SpendingAnalysis {
    let rows = ledger.covered();
    let outflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor < 0).collect();
    let inflow_rows: Vec<&Txn> = rows.iter().filter(|t| t.amount.minor > 0).collect();
    let mut notes: Vec<String> = Vec::new();

    // PAIRING FIRST. An outflow matched by an inflow of the same size on ANOTHER account within a few
    // days is money that moved, not money that left. Each inflow can be claimed ONCE — otherwise two
    // identical outflows both match one deposit and one of them is wrongly excluded.
    let mut taken_inflow = vec![false; inflow_rows.len()];
    let mut pair_of: Vec<Option<Txn>> = vec![None; outflow_rows.len()];
    for (oi, out) in outflow_rows.iter().enumerate() {
        let hit = inflow_rows.iter().enumerate().find(|(ii, i)| {
            !taken_inflow[*ii] && i.account != out.account && i.amount.minor == -out.amount.minor && days_between(&out.date, &i.date).abs() <= opts.transfer_window_days
        });
        if let Some((ii, i)) = hit {
            taken_inflow[ii] = true;
            pair_of[oi] = Some((*i).clone());
        }
    }

    let empty: &[crate::position::AccountPosition] = &[];
    let accounts = position.map(|p| p.accounts.as_slice()).unwrap_or(empty);
    let debt_accounts: Vec<&str> = accounts.iter().filter(|a| a.is_debt).map(|a| a.account.as_str()).collect();
    let debt_names: Vec<String> = accounts.iter().filter(|a| a.is_debt).map(|a| a.institution.to_lowercase()).filter(|s| !s.is_empty()).collect();

    // Keyed on the PAIR, as `recurring` groups them — a joined string would need a separator that
    // neither an account name nor a merchant key can contain.
    let recurring_keys: Vec<((String, String), String)> = recurring.iter().map(|r| ((r.account.clone(), r.key.clone()), r.label.clone())).collect();

    let outflows: Vec<ClassifiedOutflow> = outflow_rows
        .iter()
        .enumerate()
        .map(|(oi, txn)| {
            if let Some(counterpart) = pair_of[oi].clone() {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Paired, category: None, counterpart: Some(counterpart), recurring: None };
            }

            // A payment to a card the ledger does not contain has no inflow to pair with, so the only
            // remaining signal is the institution's own name in the description.
            let text = txn.description.to_lowercase();
            if !debt_accounts.contains(&txn.account.as_str()) && debt_names.iter().any(|n| text.contains(n)) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Debt, category: None, counterpart: None, recurring: None };
            }

            let key = (txn.account.clone(), merchant_key_default(&txn.description));
            if let Some((_, label)) = recurring_keys.iter().find(|(k, _)| *k == key) {
                return ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Fixed, category: categorise(&txn.description), counterpart: None, recurring: Some(label.clone()) };
            }

            ClassifiedOutflow { txn: (*txn).clone(), kind: OutflowClass::Variable, category: categorise(&txn.description), counterpart: None, recurring: None }
        })
        .collect();

    let spent: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Fixed || o.kind == OutflowClass::Variable).collect();
    let months = whole_months(&spent.iter().map(|o| o.txn.date.clone()).collect::<Vec<_>>());

    let per_month = |rows_in: &[&ClassifiedOutflow]| -> i64 {
        let totals: Vec<i64> = months
            .iter()
            .map(|m| rows_in.iter().filter(|o| month_of(&o.txn.date) == m).map(|o| -o.txn.amount.minor).sum())
            .collect();
        median(&totals)
    };

    let in_whole_months: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| months.iter().any(|m| m == month_of(&o.txn.date))).copied().collect();
    let mut by_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        match by_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_category.push((c, vec![o])),
        }
    }

    let mut by_variable_category: Vec<(&'static str, Vec<&ClassifiedOutflow>)> = Vec::new();
    for o in &in_whole_months {
        let Some(c) = o.category else { continue };
        if o.kind != OutflowClass::Variable {
            continue;
        }
        match by_variable_category.iter_mut().find(|(k, _)| *k == c) {
            Some((_, b)) => b.push(o),
            None => by_variable_category.push((c, vec![o])),
        }
    }

    let uncategorised: Vec<Txn> = in_whole_months.iter().filter(|o| o.category.is_none()).map(|o| o.txn.clone()).collect();
    if !uncategorised.is_empty() {
        let share = ((uncategorised.len() as f64 / in_whole_months.len().max(1) as f64) * 100.0).round();
        notes.push(format!(
            "{} outflow(s) — {}% of them — matched no category rule and are listed rather than bucketed as \"other\"; the category totals below do not add up to the monthly figures because of it",
            uncategorised.len(),
            share
        ));
    }
    if months.len() < 3 {
        notes.push(format!("only {} whole month(s) here — a median over that is a description of those months, not a pattern", months.len()));
    }

    let transfers: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Paired).collect();
    let debts: Vec<&ClassifiedOutflow> = outflows.iter().filter(|o| o.kind == OutflowClass::Debt).collect();
    if !transfers.is_empty() {
        notes.push(format!(
            "{} outflow(s) were matched to an inflow elsewhere and are EXCLUDED — moving money between your own accounts is not spending",
            transfers.len()
        ));
    }
    if !debts.is_empty() {
        notes.push(format!(
            "{} payment(s) to a declared debt are EXCLUDED — the obligation calendar already carries them, and counting them here would subtract the same money twice",
            debts.len()
        ));
    }

    let total_of = |os: &[&ClassifiedOutflow]| -> Money {
        let amounts: Vec<Money> = os.iter().map(|o| money(-o.txn.amount.minor, currency)).collect();
        sum(&amounts, currency).unwrap_or_else(|_| money(0, currency))
    };

    let mut categories: Vec<CategoryTotal> = by_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));
    let mut variable_categories: Vec<CategoryTotal> = by_variable_category
        .iter()
        .map(|(category, os)| CategoryTotal { category, total: total_of(os), count: os.len(), typical_month: money(per_month(os), currency) })
        .collect();
    variable_categories.sort_by_key(|c| std::cmp::Reverse(c.total.minor));

    let fixed: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Fixed).copied().collect();
    let variable: Vec<&ClassifiedOutflow> = spent.iter().filter(|o| o.kind == OutflowClass::Variable).copied().collect();

    SpendingAnalysis {
        from: rows.first().map(|t| t.date.clone()).unwrap_or_else(|| ledger.through().to_string()),
        to: ledger.through().to_string(),
        months_observed: months.len(),
        fixed_monthly: money(per_month(&fixed), currency),
        variable_monthly: money(per_month(&variable), currency),
        categories,
        variable_categories,
        transferred: total_of(&transfers),
        transfer_count: transfers.len(),
        debt_payments: total_of(&debts),
        uncategorised,
        notes,
        outflows,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;
    use crate::position::AccountPosition;
    use crate::recurring::Cadence;

    // SYNTHETIC FIXTURES ONLY — no real merchant or account reaches this repo.
    fn t(date: &str, description: &str, minor: i64, account: &str) -> Txn {
        Txn { account: account.to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn rec(label: &str, account: &str, key: &str, minor: i64) -> Recurring {
        Recurring {
            key: key.to_string(),
            label: label.to_string(),
            account: account.to_string(),
            cadence: Cadence::Monthly,
            typical: usd(minor),
            annualised: usd(0),
            occurrences: 3,
            first_seen: "2026-01-01".to_string(),
            last_seen: "2026-03-05".to_string(),
            regularity: 1.0,
            amount_stability: 1.0,
            lapsed: false,
        }
    }

    fn card_position() -> Position {
        Position {
            as_of: "2026-04-30".to_string(),
            currency: Currency::USD,
            accounts: vec![AccountPosition {
                account: "visa".to_string(),
                institution: "chase".to_string(),
                kind: Kind::Credit,
                balance: usd(-100_000),
                as_of: "2026-04-30".to_string(),
                rolled_forward: 0,
                is_debt: true,
                owed: Some(usd(100_000)),
                credit_limit: None,
                available: None,
                utilisation: None,
                apr: None,
                daily_interest: None,
                minimum_payment: None,
            }],
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(100_000),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete: true,
            provenance: "x".to_string(),
            problems: Vec::new(),
        }
    }

    fn rows() -> Vec<Txn> {
        vec![
            t("2026-01-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-01-10", "TRADER JOES #22", -8_000, "chk"),
            t("2026-01-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-01-15", "SHELL OIL 4412", -5_000, "chk"),
            t("2026-01-20", "TRANSFER TO SAVINGS", -50_000, "chk"),
            t("2026-01-21", "TRANSFER FROM CHECKING", 50_000, "sav"),
            t("2026-01-25", "CHASE CREDIT CRD EPAY", -30_000, "chk"),
            t("2026-01-28", "ZZZ MYSTERY VENDOR", -2_500, "chk"),
            t("2026-02-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-02-10", "TRADER JOES #22", -9_500, "chk"),
            t("2026-02-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-02-15", "SHELL OIL 4412", -5_500, "chk"),
            t("2026-02-25", "CHASE CREDIT CRD EPAY", -30_000, "chk"),
            t("2026-03-05", "RENT LANDLORD LLC", -120_000, "chk"),
            t("2026-03-10", "TRADER JOES #22", -7_000, "chk"),
            t("2026-03-12", "NETFLIX.COM", -1_599, "chk"),
            t("2026-03-15", "SHELL OIL 4412", -6_000, "chk"),
            t("2026-04-05", "RENT LANDLORD LLC", -120_000, "chk"),
        ]
    }

    fn analyse() -> SpendingAnalysis {
        let rows = rows();
        let ledger = crate::reconcile::unverified_ledger(&rows, "2026-04-30", "test").expect("a ledger");
        let recurring = vec![rec("RENT LANDLORD LLC", "chk", "rent landlord", 120_000), rec("NETFLIX.COM", "chk", "netflix", 1_599)];
        analyse_spending(&ledger, Some(&card_position()), &recurring, Currency::USD, &SpendingOptions::default())
    }

    #[test]
    fn the_category_table_places_what_it_can_and_admits_what_it_cannot() {
        // Measured against the TypeScript, first-match-wins order included.
        assert_eq!(categorise("RENT LANDLORD LLC"), Some("housing"));
        assert_eq!(categorise("SHELL OIL 4412"), Some("fuel"));
        assert_eq!(categorise("TRADER JOES #22"), Some("groceries"));
        assert_eq!(categorise("AMZN Mktp US"), Some("shopping"));
        assert_eq!(categorise("NETFLIX.COM"), Some("subscriptions"));
        assert_eq!(categorise("DOORDASH*BURGER"), Some("dining"));
        // "ATM WITHDRAWAL" hits `fees` before `cash` — fees is EARLIER in the table, and first match
        // wins. That is the table being data rather than logic, and it is worth pinning.
        assert_eq!(categorise("ATM WITHDRAWAL"), Some("fees"));
        assert_eq!(categorise("Target RedCard"), Some("shopping"), "matching is case-insensitive");
        // NONE, not "other". A large uncategorised pile is an admission; a large "other" hides it.
        assert_eq!(categorise("CHASE CREDIT CRD EPAY"), None);
        assert_eq!(categorise("ZZZ UNKNOWN THING"), None);
        assert_eq!(CATEGORY_RULES.len(), 15, "the table lost or gained a rule");
    }

    #[test]
    fn a_transfer_between_your_own_accounts_is_not_spending() {
        let a = analyse();
        assert_eq!(a.transfer_count, 1);
        assert_eq!(a.transferred.minor, 50_000);
        let paired: Vec<&ClassifiedOutflow> = a.outflows.iter().filter(|o| o.kind == OutflowClass::Paired).collect();
        assert_eq!(paired.len(), 1);
        assert_eq!(paired[0].counterpart.as_ref().expect("the other side").account, "sav");
        // It is NOT in the monthly figures. Counting it would subtract the same money twice from
        // the runway, which looks like prudence and is simply wrong.
        assert!(a.notes.iter().any(|n| n.contains("moving money between your own accounts is not spending")));
    }

    #[test]
    fn a_payment_to_a_declared_debt_is_excluded_because_the_calendar_already_has_it() {
        let a = analyse();
        assert_eq!(a.debt_payments.minor, 60_000, "two payments of 30000");
        let debts: Vec<&ClassifiedOutflow> = a.outflows.iter().filter(|o| o.kind == OutflowClass::Debt).collect();
        assert_eq!(debts.len(), 2);
        // Matched by the INSTITUTION's name in the description — "CHASE CREDIT CRD EPAY" against a
        // declared chase card — because a payment to a card the ledger does not hold has no inflow
        // to pair with.
        assert!(debts.iter().all(|d| d.txn.description.contains("CHASE")));
        assert!(a.notes.iter().any(|n| n.contains("subtract the same money twice")));
    }

    #[test]
    fn fixed_and_variable_are_separated_because_only_one_of_them_is_a_choice() {
        let a = analyse();
        // Measured by running finance-spending.ts on this exact fixture.
        assert_eq!(a.months_observed, 2, "Jan and Apr are partial and are dropped");
        assert_eq!(a.fixed_monthly.minor, 121_599, "rent + netflix, matched to detected recurring charges");
        assert_eq!(a.variable_monthly.minor, 14_000, "groceries + fuel");
        assert_eq!(discretionary_monthly(&a).minor, 14_000, "runway gets the VARIABLE figure only");
        // The fixed half is deliberately excluded: the obligation calendar already carries it, and a
        // runway subtracting both would double-count every subscription it knows about.
        assert_ne!(discretionary_monthly(&a).minor, a.fixed_monthly.minor + a.variable_monthly.minor);
    }

    #[test]
    fn the_variable_split_excludes_the_fixed_charges_the_calendar_already_carries() {
        let a = analyse();
        // `categories` answers "where does my money go" and RIGHTLY includes rent and the
        // subscription. Anything that also counts the obligation calendar must not.
        assert_eq!(a.categories.iter().map(|c| c.category).collect::<Vec<_>>(), vec!["housing", "groceries", "fuel", "subscriptions"]);
        assert_eq!(a.variable_categories.iter().map(|c| c.category).collect::<Vec<_>>(), vec!["groceries", "fuel"]);
        // The gap between the two IS the double-count that `viable` used to make: 120000 of rent
        // plus 1599 of subscription, counted once on the calendar and again as "variable".
        let all: i64 = a.categories.iter().map(|c| c.typical_month.minor).sum();
        let var: i64 = a.variable_categories.iter().map(|c| c.typical_month.minor).sum();
        assert_eq!(all - var, 121_599);
        assert_eq!(var, 14_000, "and this matches the honest variableMonthly figure");
        assert_eq!(var, a.variable_monthly.minor);
    }

    #[test]
    fn the_categories_are_biggest_first_because_that_is_the_order_to_act_in() {
        let a = analyse();
        let got: Vec<(&str, i64, usize, i64)> = a.categories.iter().map(|c| (c.category, c.total.minor, c.count, c.typical_month.minor)).collect();
        assert_eq!(
            got,
            vec![("housing", 240_000, 2, 120_000), ("groceries", 16_500, 2, 8_250), ("fuel", 11_500, 2, 5_750), ("subscriptions", 3_198, 2, 1_599)]
        );
        assert_eq!(top_categories(&a, 3).iter().map(|c| c.category).collect::<Vec<_>>(), vec!["housing", "groceries", "fuel"]);
        // Asking for more than there are is not an error and does not panic.
        assert_eq!(top_categories(&a, 99).len(), 4);
        assert_eq!(top_categories(&a, 0).len(), 0);
    }

    #[test]
    fn an_unplaceable_outflow_is_listed_rather_than_bucketed_as_other() {
        // The mystery vendor is in JANUARY, which is a partial month and therefore outside the
        // medians — so it is correctly absent here.
        let a = analyse();
        assert!(a.uncategorised.is_empty(), "the only unplaceable row is in a trimmed partial month");

        // Move it into a whole month and it surfaces, with the share it represents.
        let mut r = rows();
        r.push(t("2026-02-18", "ZZZ MYSTERY VENDOR", -2_500, "chk"));
        r.sort_by(|a, b| a.date.cmp(&b.date));
        let ledger = crate::reconcile::unverified_ledger(&r, "2026-04-30", "test").expect("a ledger");
        let a2 = analyse_spending(&ledger, Some(&card_position()), &[rec("RENT LANDLORD LLC", "chk", "rent landlord", 120_000)], Currency::USD, &SpendingOptions::default());
        assert_eq!(a2.uncategorised.len(), 1);
        assert_eq!(a2.uncategorised[0].description, "ZZZ MYSTERY VENDOR");
        assert!(a2.notes.iter().any(|n| n.contains("rather than bucketed as \"other\"")));
        assert!(a2.notes.iter().any(|n| n.contains("do not add up")), "the shortfall in the category totals is stated");
    }

    #[test]
    fn one_inflow_can_only_pair_with_one_outflow() {
        // Two identical outflows and ONE matching deposit. Without the claim, both would read as
        // transfers and real spending would vanish from the analysis.
        let r = vec![
            t("2026-02-01", "TRANSFER TO SAVINGS", -50_000, "chk"),
            t("2026-02-02", "PAYMENT TO SOMEONE", -50_000, "chk"),
            t("2026-02-02", "TRANSFER FROM CHECKING", 50_000, "sav"),
        ];
        let ledger = crate::reconcile::unverified_ledger(&r, "2026-02-28", "test").expect("a ledger");
        let a = analyse_spending(&ledger, None, &[], Currency::USD, &SpendingOptions::default());
        assert_eq!(a.transfer_count, 1, "exactly one of the two is paired");
        assert_eq!(a.outflows.iter().filter(|o| o.kind == OutflowClass::Variable).count(), 1);
    }

    #[test]
    fn a_same_account_move_is_not_a_transfer_and_a_distant_one_is_not_either() {
        let same = vec![t("2026-02-01", "MOVE", -50_000, "chk"), t("2026-02-02", "MOVE BACK", 50_000, "chk")];
        let l1 = crate::reconcile::unverified_ledger(&same, "2026-02-28", "test").expect("a ledger");
        assert_eq!(analyse_spending(&l1, None, &[], Currency::USD, &SpendingOptions::default()).transfer_count, 0, "the inflow must be on ANOTHER account");

        let distant = vec![t("2026-02-01", "MOVE", -50_000, "chk"), t("2026-02-20", "ARRIVE", 50_000, "sav")];
        let l2 = crate::reconcile::unverified_ledger(&distant, "2026-02-28", "test").expect("a ledger");
        assert_eq!(analyse_spending(&l2, None, &[], Currency::USD, &SpendingOptions::default()).transfer_count, 0, "19 days apart is not one transfer");
        // Widen the window and the same pair matches — the threshold is a policy, not a fact.
        let wide = SpendingOptions { transfer_window_days: 30 };
        assert_eq!(analyse_spending(&l2, None, &[], Currency::USD, &wide).transfer_count, 1);
    }

    #[test]
    fn thin_coverage_is_stated_rather_than_presented_as_a_pattern() {
        let a = analyse();
        assert!(a.notes.iter().any(|n| n.contains("a description of those months, not a pattern")));
        assert_eq!(a.from, "2026-01-05", "the first covered row");
        assert_eq!(a.to, "2026-04-30", "the ledger's coverage, not the last row");
    }
